import { crc32, deflateSync } from "node:zlib"

// Lienzos grises de 16×16 generados con System.Drawing, sin personas ni datos reales.
const JPEG_OSCURO =
  ""
const JPEG_CLARO =
  ""

/** JPEG real sintético con Exif y comentario ficticios para probar su retirada. */
export function jpegSintetico(variante = false): Buffer {
  const segmento = (marcador: number, datos: Buffer) => {
    const longitud = Buffer.alloc(2)
    longitud.writeUInt16BE(datos.length + 2)
    return Buffer.concat([Buffer.from([0xff, marcador]), longitud, datos])
  }
  return Buffer.concat([
    Buffer.from([0xff, 0xd8]),
    segmento(0xe1, Buffer.from("Exif\0\0GPS 41.3874N 2.1686E sintetico", "latin1")),
    segmento(0xfe, Buffer.from("comentario sintetico", "latin1")),
    Buffer.from(variante ? JPEG_CLARO : JPEG_OSCURO, "base64").subarray(2),
  ])
}

/** PNG 1×1 RGB sintético, o un IDAT deliberadamente inválido para regresiones. */
export function pngSintetico(idat = deflateSync(Buffer.from([0, 255, 255, 255]))): Buffer {
  const bloque = (tipo: string, datos: Buffer) => {
    const tipoYDatos = Buffer.concat([Buffer.from(tipo, "ascii"), datos])
    const longitud = Buffer.alloc(4)
    longitud.writeUInt32BE(datos.length)
    const crc = Buffer.alloc(4)
    crc.writeUInt32BE(crc32(tipoYDatos))
    return Buffer.concat([longitud, tipoYDatos, crc])
  }
  const ihdr = Buffer.alloc(13)
  ihdr.writeUInt32BE(1, 0)
  ihdr.writeUInt32BE(1, 4)
  ihdr[8] = 8
  ihdr[9] = 2
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    bloque("IHDR", ihdr),
    bloque("IDAT", idat),
    bloque("IEND", Buffer.alloc(0)),
  ])
}

/** Ruta relativa (con su consulta firmada) de un enlace del almacén local. */
export function rutaDeEnlace(url: string): string {
  const enlace = new URL(url)
  return `${enlace.pathname}${enlace.search}`
}
